            onFinished={() => {}}
            {...toLeftOrRightOf(containerRef.current.getBoundingClientRect(), 0)}
        >
            <IconizedContextMenuOptionList>{deviceOptions}</IconizedContextMenuOptionList>
        </IconizedContextMenu>
    );
};

